{"results": [{"id": "hp_doc_71a256d4619424d89b5e9b7c7f908437cb95d0f9849c1914f68e573ecf0ece5c", "title": "Jimmy Jerkens", "text": "James A. \"Jimmy\" Jerkens (born January 24, 1959 in Bay Shore, New York) is an American Thoroughbred horse trainer. His father, U.S. Racing Hall of Fame inductee H. Allen Jerkens, and brother, Steve Jerkens, are also trainers.", "score": 35.5325}, {"id": "hp_doc_6426d24853f91d08ed6ca50c81e4addf9494c805dbf4eaff042575058ed8b311", "title": "Sonny Hine", "text": "Hubert \"Sonny\" Hine (January 9, 1931 – March 17, 2000) was an American Hall of Fame Thoroughbred horse trainer best known as the trainer of 1998 U.S. Horse of the Year, Skip Away.", "score": 29.2304}, {"id": "hp_doc_694785b287822e03cf64629c41732591c4adcfca416b7e2612c13bce92b4fb2d", "title": "Josie Carroll", "text": "Josie Carroll (born December 8, 1957 in Scarborough, Ontario) is a Canadian Thoroughbred horse trainer and the first woman trainer to win the Queen's Plate, the oldest thoroughbred horse race in Canada and Canada's most prestigious race.", "score": 27.0307}], "remaining_searches": 2}
